+  /* An NPC hull, a raider with her renown, trains crews but moves none. */
+  strlcpy(victor->owner, "Corr", sizeof(victor->owner));
+  victor->renown = 0;
+  target->owner[0] = '\0';
+  target->renown = 2000;
+  CuAssertIntEquals(tc, 0, vessel_settle_sinking(target, victor));
