+void Test_vessel_renown_gates_the_hiring_hall(CuTest *tc)
+{
+  struct rewards_berth berth;
+  struct greyhawk_ship_data *ship;
+  const char *output;
+
+  ship = rewards_berth_begin(tc, &berth, VESSEL_SHIP);
